import{a as e,c as t,i as n,l as r,o as i,r as a,s as o,t as s,u as c}from"./app-C4mzCnKe.js";var l=JSON.parse(`{"path":"/","title":"股票交易策略生成智能体系统","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"README.md"}`),u={name:`README.md`};function d(s,l,u,d,f,p){let m=r(`RouteLink`);return t(),n(`div`,null,[l[7]||=e(`<h1 id="股票交易策略生成智能体系统" tabindex="-1"><a class="header-anchor" href="#股票交易策略生成智能体系统"><span>股票交易策略生成智能体系统</span></a></h1><p>多 Agent 架构 · 自我进化 · 外挂评测平台 · 会话过程可观测</p><blockquote><p><strong>PLAN-03 · v3</strong> · 架构设计方案。两段式编排：<strong>主控</strong>（意图/规划）+ <strong>调度器</strong>（运行时）。判决器先行。</p></blockquote><h2 id="两条纵贯线-横切关注点" tabindex="-1"><a class="header-anchor" href="#两条纵贯线-横切关注点"><span>两条纵贯线（横切关注点）</span></a></h2><p>本系统有两个<strong>横切关注点</strong>，贯穿所有面、所有 Agent、所有任务——不是两个独立功能，而是两条纵贯线：</p><ol><li><strong>可观测纵贯线（Observability）</strong> — 每个 Agent 每回合都产出结构化 span（四元 id + 三层语义 + 8 类 span），写 append-only Trace 总线。一切决策可回放、可归因、可复核。</li><li><strong>自进化纵贯线（Self-evolution）</strong> — 每个 Agent 的输出最终落到「冻结层（判决器/口径/回测引擎）+ 两个可进化层（策略/因子 + prompt/skill/协议）」；裁决面输出 → 归因 → 影子回放门禁 → 晋级/回滚。</li></ol>`,6),a(`p`,null,[l[2]||=i(`这两条线是`,-1),l[3]||=a(`strong`,null,`同一条反馈回路的两个视角`,-1),l[4]||=i(`：可观测负责「建立事实」，自进化负责「依据事实改进」。可观测是自进化的输入（归因靠 trace），自进化是可观测的目的（观测是为了改进）。详见 `,-1),o(m,{to:`/observability.html`},{default:c(()=>[...l[0]||=[i(`可观测平台设计`,-1)]]),_:1}),l[5]||=i(` 与 `,-1),o(m,{to:`/self-evolution.html`},{default:c(()=>[...l[1]||=[i(`自进化设计`,-1)]]),_:1}),l[6]||=i(`。`,-1)]),l[8]||=e(`<h2 id="核心结论" tabindex="-1"><a class="header-anchor" href="#核心结论"><span>核心结论</span></a></h2><ul><li><strong>Agent 总数</strong>：13 个运行时 Agent（另 + 1 个外挂评测平台）</li><li><strong>切分</strong>：门面/决策面 6 · 裁决面 3 · 平台面 4；协议设计是治理工件，不设 Agent</li><li><strong>模型主线</strong>：DeepSeek Flash 管高频/例行/视觉；Pro 管深推理/质量/意图规划；智谱 GLM 做异源第二意见与降级冗余</li><li><strong>评测接入</strong>：Trace 总线 push → 采集/评测/反馈三层，四元 id 贯穿，平台对生产只读</li><li><strong>自我进化</strong>：trace → 分析 → 优化 → 影子回放 → 晋级/回滚，回归门禁</li></ul><h2 id="六条设计原则" tabindex="-1"><a class="header-anchor" href="#六条设计原则"><span>六条设计原则</span></a></h2><ol><li><strong>判决器优先、物理隔离</strong> — 评测/回测/对账跑在与策略生成不同的进程、代码仓，只读生产数据。</li><li><strong>以「日」为独立样本</strong> — 同日多股相关，不用交易笔数虚增自由度；配对检验对齐日期，n≥5。</li><li><strong>未经严谨考证的数据不用于决策</strong> — 字段带口径/单位/来源/复权基准，知识卡带证据等级。</li><li><strong>先看机会再看风险，用概率与权重</strong> — 不做&quot;一刀否决&quot;，判决器输出概率而非二元。</li><li><strong>复盘永远执行且基于事实</strong> — 结果不可质疑，被质疑的是决策时的动作、抓手与依据；更差即回滚。</li><li><strong>一切过程可回放</strong> — trace 贯穿四元 id，评测平台只看 trace 与结果。</li></ol><h2 id="图例" tabindex="-1"><a class="header-anchor" href="#图例"><span>图例</span></a></h2><table><thead><tr><th>颜色</th><th>含义</th></tr></thead><tbody><tr><td>🟠 琥珀</td><td>决策面（α，产生判断/动作）</td></tr><tr><td>🟢 青绿</td><td>裁决面（判决器，物理隔离）</td></tr><tr><td>🔵 蓝</td><td>平台面（资产/能力/协议）</td></tr><tr><td>🟣 紫</td><td>外挂评测平台</td></tr><tr><td>⚪ 灰</td><td>共享总线 / 基础设施</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">怎么读</p><p>建议顺序：<code>总架构</code> → <code>Agent 清单</code> → <code>提示词与模式</code> → <code>任务映射</code> → <code>模型选型</code> → <code>决策生命周期</code> → <code>评测与可观测</code> → <code>可观测平台设计</code> → <code>评估器设计</code> → <code>评测集设计</code> → <code>自进化设计</code> → <code>协议</code> → <code>落地路线</code>。</p></div>`,7)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};